import sys

def main():
    data = sys.stdin.read().split()
    n, target = int(data[0]), int(data[1])
    nums = [int(x) for x in data[2:2 + n]]
    reach = [False] * (target + 1)
    reach[0] = True
    for v in nums:
        if v > target:
            continue
        for s in range(target, v - 1, -1):
            if reach[s - v]:
                reach[s] = True
    print('YES' if reach[target] else 'NO')

main()

